bool optional_chaining = false;
bool is_optional = false;
int optional_link_begin;
do {
  switch (peek()) {
    case Token::kQuestionPeriod: {
      if (is_optional) {
        ReportUnexpectedToken(peek());
        return impl()->FailureExpression();
      }
      // Include the ?. in the source range position.
      optional_link_begin = scanner()->peek_location().beg_pos;
      Consume(Token::kQuestionPeriod);
      is_optional = true;
      optional_chaining = true;
      if (Token::IsPropertyOrCall(peek())) continue;
      int pos = position();
      ExpressionT key = ParsePropertyOrPrivatePropertyName();
      result = factory()->NewProperty(result, key, pos, is_optional);
      break;
    }

    /* Property */
    case Token::kLeftBracket: {
      Consume(Token::kLeftBracket);
      int pos = position();
      AcceptINScope scope(this, true);
      ExpressionT index = ParseExpressionCoverGrammar();
      result = factory()->NewProperty(result, index, pos, is_optional);
      Expect(Token::kRightBracket);
      break;
    }

    /* Property */
    case Token::kPeriod: {
      if (is_optional) {
        ReportUnexpectedToken(Next());
        return impl()->FailureExpression();
      }
      Consume(Token::kPeriod);
      int pos = position();
      ExpressionT key = ParsePropertyOrPrivatePropertyName();
      result = factory()->NewProperty(result, key, pos, is_optional);
      break;
    }

    /* Call */
    case Token::kLeftParen: {
      int pos;
      if (Token::IsCallable(scanner()->current_token())) {
        // For call of an identifier we want to report position of
        // the identifier as position of the call in the stack trace.
        pos = position();
      } else {
        // For other kinds of calls we record position of the parenthesis as
        // position of the call. Note that this is extremely important for
        // expressions of the form function(){...}() for which call position
        // should not point to the closing brace otherwise it will intersect
        // with positions recorded for function literal and confuse debugger.
        pos = peek_position();
        // Also the trailing parenthesis are a hint that the function will
        // be called immediately. If we happen to have parsed a preceding
        // function literal eagerly, we can also compile it eagerly.
        if (result->IsFunctionLiteral()) {
          result->AsFunctionLiteral()->SetShouldEagerCompile();
        }
      }
      bool has_spread;
      ExpressionListT args(pointer_buffer());
      ParseArguments(&args, &has_spread);

      // Keep track of eval() calls since they disable all local variable
      // optimizations.
      // The calls that need special treatment are the
      // direct eval calls. These calls are all of the form eval(...), with
      // no explicit receiver.
      // These calls are marked as potentially direct eval calls. Whether
      // they are actually direct calls to eval is determined at run time.
      int eval_scope_info_index = 0;
      if (CheckPossibleEvalCall(result, is_optional, scope())) {
        eval_scope_info_index = GetNextInfoId();
      }

      result = factory()->NewCall(result, args, pos, has_spread,
                                  eval_scope_info_index, is_optional);

      fni_.RemoveLastFunction();
      break;
    }

    default:
      // Template literals in/after an Optional Chain not supported:
      if (optional_chaining) {
        impl()->ReportMessageAt(scanner()->peek_location(),
                                MessageTemplate::kOptionalChainingNoTemplate);
        return impl()->FailureExpression();
      }
      /* Tagged Template */
      DCHECK(Token::IsTemplate(peek()));
      result = ParseTemplateLiteral(result, position(), true);
      break;
  }
  if (is_optional) {
    SourceRange chain_link_range(optional_link_begin, end_position());
    impl()->RecordExpressionSourceRange(result, chain_link_range);
    is_optional = false;
  }
} while (Token::IsPropertyOrCall(peek()));
if (optional_chaining) return factory()->NewOptionalChain(result);
return result;

BasicBlock* block;
DeoptFrame* deopt_frame;
auto GetDeoptFrame = [](BasicBlock* block) {
  return &block->control_node()
              ->Cast<CheckpointedJump>()
              ->eager_deopt_info()
              ->top_frame();
};
switch (hoist_untagging[input_index]) {
  case HoistType::kLoopEntryUnchecked:
    block = phi->merge_state()->predecessor_at(input_index);
    deopt_frame = nullptr;
    break;
  case HoistType::kLoopEntry:
    block = phi->merge_state()->predecessor_at(input_index);
    deopt_frame = GetDeoptFrame(block);
    break;
  case HoistType::kPrologue:
    block = *builder_->graph()->begin();
    deopt_frame = GetDeoptFrame(block);
    break;
  case HoistType::kNone:
    UNREACHABLE();
}
// Ensure the hoisted value is actually live at the hoist location.
CHECK(input->Is<InitialValue>() ||
      (phi->is_loop_phi() && !phi->is_backedge_offset(input_index)));
ValueNode* untagged;
switch (repr) {
  case ValueRepresentation::kInt32:
    if (!deopt_frame) {
      DCHECK(
          NodeTypeIs(StaticTypeForNode(builder_->broker(),
                                       builder_->local_isolate(), input),
                     NodeType::kSmi));
      untagged = AddNodeAtBlockEnd(
          NodeBase::New<UnsafeSmiUntag>(builder_->zone(), {input}),
          block);

    } else {
      untagged = AddNodeAtBlockEnd(
          NodeBase::New<CheckedNumberOrOddballToFloat64>(
              builder_->zone(), {input},
              TaggedToFloat64ConversionType::kOnlyNumber),
          block, deopt_frame);
      untagged =
          AddNodeAtBlockEnd(NodeBase::New<CheckedTruncateFloat64ToInt32>(
                                builder_->zone(), {untagged}),
                            block, deopt_frame);
    }
    break;
  case ValueRepresentation::kFloat64:
  case ValueRepresentation::kHoleyFloat64:
    if (!deopt_frame) {
      DCHECK(
          NodeTypeIs(StaticTypeForNode(builder_->broker(),
                                       builder_->local_isolate(), input),
                     NodeType::kNumber));
      untagged = AddNodeAtBlockEnd(
          NodeBase::New<UncheckedNumberOrOddballToFloat64>(
              builder_->zone(), {input},
              TaggedToFloat64ConversionType::kOnlyNumber),
          block);
    } else {
      DCHECK(!phi->uses_require_31_bit_value());
      untagged = AddNodeAtBlockEnd(
          NodeBase::New<CheckedNumberOrOddballToFloat64>(
              builder_->zone(), {input},
              TaggedToFloat64ConversionType::kOnlyNumber),
          block, deopt_frame);
      if (repr != ValueRepresentation::kHoleyFloat64) {
        untagged =
            AddNodeAtBlockEnd(NodeBase::New<CheckedHoleyFloat64ToFloat64>(
                                  builder_->zone(), {untagged}),
                              block, deopt_frame);
      }
    }
    break;
  case ValueRepresentation::kTagged:
  case ValueRepresentation::kUint32:
  case ValueRepresentation::kIntPtr:
    UNREACHABLE();
}
phi->change_input(input_index, untagged);

VirtualObject* Clone(uint32_t new_object_id, Zone* zone,
                     bool empty_clone = false) const {
  VirtualObject* result;
  switch (type_) {
    case kHeapNumber:
    case kFixedDoubleArray:
    case kConsString:
      UNREACHABLE();
    case kDefault: {
      ValueNode** slots = zone->AllocateArray<ValueNode*>(slot_count());
      result = NodeBase::New<VirtualObject>(zone, 0, map(), new_object_id,
                                            slot_count(), slots);
      break;
    }
  }
  if (empty_clone) return result;

  // Copy content
  switch (type_) {
    case kHeapNumber:
    case kFixedDoubleArray:
    case kConsString:
      UNREACHABLE();
    case kDefault: {
      for (uint32_t i = 0; i < slot_count(); i++) {
        result->set_by_index(i, get_by_index(i));
      }
      break;
    }
  }
  result->set_allocation(allocation());
  return result;
}

icu::UnicodeString ReplaceHourCycleInPattern(icu::UnicodeString pattern,
                                             JSDateTimeFormat::HourCycle hc) {
  char16_t replacement;
  switch (hc) {
    case JSDateTimeFormat::HourCycle::kUndefined:
      return pattern;
    case JSDateTimeFormat::HourCycle::kH11:
      replacement = 'K';
      break;
    case JSDateTimeFormat::HourCycle::kH12:
      replacement = 'h';
      break;
    case JSDateTimeFormat::HourCycle::kH23:
      replacement = 'H';
      break;
    case JSDateTimeFormat::HourCycle::kH24:
      replacement = 'k';
      break;
  }
  bool replace = true;
  icu::UnicodeString result;
  char16_t last = u'\0';
  for (int32_t i = 0; i < pattern.length(); i++) {
    char16_t ch = pattern.charAt(i);
    switch (ch) {
      case '\'':
        replace = !replace;
        result.append(ch);
        break;
      case 'H':
        [[fallthrough]];
      case 'h':
        [[fallthrough]];
      case 'K':
        [[fallthrough]];
      case 'k':
        // If the previous field is a day, add a space before the hour.
        if (replace && last == u'd') {
          result.append(' ');
        }
        result.append(replace ? replacement : ch);
        break;
      default:
        result.append(ch);
        break;
    }
    last = ch;
  }
  return result;
}

void CompleteArrayBufferSweeping(Heap* heap) {
  auto* array_buffer_sweeper = heap->array_buffer_sweeper();
  if (array_buffer_sweeper->sweeping_in_progress()) {
    auto* tracer = heap->tracer();
    GCTracer::Scope::ScopeId scope_id;

    switch (tracer->GetCurrentCollector()) {
      case GarbageCollector::MINOR_MARK_SWEEPER:
        scope_id = GCTracer::Scope::MINOR_MS_COMPLETE_SWEEP_ARRAY_BUFFERS;
        break;
      case GarbageCollector::SCAVENGER:
        scope_id = GCTracer::Scope::SCAVENGER_COMPLETE_SWEEP_ARRAY_BUFFERS;
        break;
      case GarbageCollector::MARK_COMPACTOR:
        scope_id = GCTracer::Scope::MC_COMPLETE_SWEEP_ARRAY_BUFFERS;
    }

    TRACE_GC_EPOCH_WITH_FLOW(
        tracer, scope_id, ThreadKind::kMain,
        array_buffer_sweeper->GetTraceIdForFlowEvent(scope_id),
        TRACE_EVENT_FLAG_FLOW_IN);
    array_buffer_sweeper->EnsureFinished();
  }
}
